renderer.valueExpression:
var time = $feature.MaxDuratio
if (time < 60) {
    return '≤ 1 Hour'
}
else if (time ==60){
    return '1 Hour'
}
else if (time ==120){
    return '2 Hours'
}
else if (time ==180){
    return '3 Hours'
}
else if (time ==360){
    return '6 Hours'
}

expressionInfos.expression:
var Entrance = $feature.ENTRANCE
var Visitor = $feature.VisitorEnt

if (IsEmpty(Entrance)==true && (IsEmpty(Visitor))){
    return ''
}

else if (IsEmpty(Entrance)==false && (IsEmpty(Visitor)==true)) {
return 'Entrance: ' + Entrance
}

else if (IsEmpty(Entrance)==false && (IsEmpty(Visitor)==false)) {
return  'Permit-Only Entrance: ' + Entrance + TextFormatting.NewLine + 'Visitor Entrance: ' + Visitor
}

var publicspace = $feature.PUBLIC_SPA
var totalspace = $feature.TOTAL_SPAC
if (IsEmpty(publicspace)==true){
    return ''
}
else if ((IsEmpty(totalspace)==false) && (publicspace>0)){
return '('+ publicspace + ' Public Spaces)'
}

else if ((totalspace==0) && (IsEmpty(publicspace)==false)){
return + publicspace + ' Public Spaces' + TextFormatting.NewLine + TextFormatting.NewLine
}

var Evening = $feature.EveningBeg
if (IsEmpty(Evening)==true){
    return ''
}
else {
return 'Evening rates begin at ' + Evening
}

var Evening = $feature.EveningBeg
if (IsEmpty(Evening)==true){
    return ''
}
else {
return '*'
}

var events = $feature["SPECIAL_EV"]
if (IsEmpty(events) == true){
    return ''
}
else return 'Special events rate: ' + events

var monthly = $feature["MONTHLY_RA"]
if (IsEmpty(monthly) == true){
    return ''
}
else return '<tr><td style="border:0.5px solid rgb(215,215,215)">Monthly Rate</td><td style="border:0.5px solid rgb(215,215,215)">{MONTHLY_RATE}<br /></td></tr></tbody></table>'

var totalspace = $feature["TOTAL_SPAC"]
if (IsEmpty(totalspace)==true){
    return ''
}
if (totalspace==0){
    return ''
}
else {
return totalspace + ' Spaces'
}

var notes = $feature["SPACE_NOTE"]
if (IsEmpty(notes)==true){
    return ''

}
else if ((IsEmpty(notes)==false) && ($feature.NAME =='Triangle Lot')) {
return notes + TextFormatting.NewLine + 'Open to public from 6PM-6AM'
}

else {
    return notes
}

